        (3, 'As it happens, oceans and continents are not distributed', 13.0, 'NotoSerif-Regular', False, 2301728, 67.8, 117.8, 438.4, 136.5),
        (3, 'equally between the Northern and Southern Hemispheres.', 13.0, 'NotoSerif-Regular', False, 2301728, 67.8, 135.9, 437.2, 154.5),
        (3, 'Fig. 2.2. Maps of the Earth as seen from above the North Pole (left) and above', 10.0, 'NotoSerif-MediumItalic', False, 5790043, 68.0, 386.6, 437.4, 400.9),
        (3, 'the South Pole (right).', 10.0, 'NotoSerif-MediumItalic', False, 5790043, 199.2, 398.6, 303.6, 412.9),
        (3, 'Let us examine the two maps in Fig. 2.2. Here too, the blue', 13.0, 'NotoSerif-Regular', False, 2301728, 67.8, 426.8, 438.4, 445.5),
