        (3, 'which have various names — ‘sea’, ‘bay’, ‘gulf’, etc.', 13.0, 'NotoSerif-Regular', False, 2301728, 67.8, 462.5, 382.9, 481.5),
        (3, 'LET’S EXPLORE', 14.0, 'NotoSans-Bold', True, 16777215, 76.8, 493.0, 181.4, 513.4),
        (3, 'Æ What are the circular lines in each map called? And do', 12.0, 'NotoSerif-Regular', False, 2301728, 72.3, 521.7, 441.2, 538.9),
        (3, 'you know what the lines radiating out of the two poles are', 12.0, 'NotoSerif-Regular', False, 2301728, 94.8, 539.7, 438.1, 556.9),
        (3, 'called? (Hint: you studied them in the previous chapter, but', 12.0, 'NotoSerif-Italic', False, 2301728, 94.8, 557.7, 438.1, 574.9),
        (3, 'here they are presented differently.)', 12.0, 'NotoSerif-Italic', False, 2301728, 94.8, 575.7, 293.1, 592.9),
        (3, 'Æ Which hemisphere holds more water?', 12.0, 'NotoSerif-Regular', False, 2301728, 72.3, 596.2, 316.5, 613.4),
        (3, 'Æ What do you think could be the approximate proportion', 12.0, 'NotoSerif-Regular', False, 2301728, 72.3, 616.7, 438.1, 633.9),
        (3, 'of water to land in the Northern Hemisphere? And in the', 12.0, 'NotoSerif-Regular', False, 2301728, 94.8, 634.7, 438.1, 651.9),
        (3, 'Southern Hemisphere? Discuss in groups.', 12.0, 'NotoSerif-Regular', False, 2301728, 94.8, 652.7, 332.0, 669.9),
