        (2, '1 The First World War, Khilafat and Non-Cooperation', 18.0, 'RotisSansSerif-ExtraBold', True, 33143, 38.4, 54.1, 443.5, 72.1),
        (2, 'In the years after 1919, we see the national movement spreading to', 11.5, 'TT274T00', False, 2301728, 34.3, 115.9, 318.3, 127.4),
